import limited_client as robot, numpy as np
from urllib.error import HTTPError
obs=robot.observe(camera=2); print('initial',obs['robot'],'status',robot.status(),flush=True)
for j in range(6):
    r=robot.observe(camera=2)['robot']; q=np.array(r['joint_positions'],float); p=np.array(r['tcp_position'],float)
    t=q.copy(); t[j]+=0.06
    try:
        for _ in range(2): robot.step(t.tolist()+[0.04,0.04])
    except HTTPError as e:
        print('probe-error',j,e.code,e.read().decode(errors='replace'),flush=True); break
    rp=robot.observe(camera=2)['robot']; qp=np.array(rp['joint_positions'],float); pp=np.array(rp['tcp_position'],float)
    print('probe',j,'dq',qp-q,'tcp-delta',pp-p,flush=True)
    back=qp.copy(); back[j]=q[j]
    try:
        for _ in range(2): robot.step(back.tolist()+[0.04,0.04])
    except HTTPError as e:
        print('return-error',j,e.code,e.read().decode(errors='replace'),flush=True); break
    rb=robot.observe(camera=2)['robot']; print('returned',j,'tcp',rb['tcp_position'],'status',robot.status(),flush=True)
